function validate([text, brokenLetters]) {
  if (typeof text !== 'string' || text.length < 1 || text.length > 10000) return 'text needs 1 to 10000 characters.';
  if (!/^[a-z]+( [a-z]+)*$/.test(text)) return 'text is lowercase words joined by single spaces.';
  if (typeof brokenLetters !== 'string' || !/^[a-z]*$/.test(brokenLetters)) return 'brokenLetters holds only lowercase letters.';
  if (new Set(brokenLetters).size !== brokenLetters.length) return 'brokenLetters cannot repeat a letter.';
  return null;
}

