function canBeTypedWords(text, brokenLetters) {
  const broken = new Set(brokenLetters);
  let count = 0;
  for (const word of text.split(' ')) {
    let typeable = true;
    for (const letter of word) {
      if (broken.has(letter)) {
        typeable = false;
        break;
      }
    }
    if (typeable) {
      count++;
    }
  }
  return count;
}

