function canBeTypedWords(text, brokenLetters) {
  // Walk the text one character at a time, remembering whether the current word has hit a dead key.
  let total = 0, spoiled = false;
  for (let i = 0; i <= text.length; i++) {
    if (i === text.length || text[i] === ' ') {
      if (!spoiled) total++;
      spoiled = false;
    } else if (brokenLetters.indexOf(text[i]) !== -1) {
      spoiled = true;
    }
  }
  return total;
}

