function generate(rand, size) {
  const alphabet = 'abcdefghijklmnopqrstuvwxyz';
  const pickLetters = (pool, count) => {
    const letters = pool.split('');
    for (let i = letters.length - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [letters[i], letters[j]] = [letters[j], letters[i]];
    }
    return letters.slice(0, count).join('');
  };
  if (size === 'large') {
    const words = [];
    let length = -1;
    for (;;) {
      const wordLength = 1 + Math.floor(rand() * 8);
      if (length + 1 + wordLength > 9990) break;
      let word = '';
      for (let i = 0; i < wordLength; i++) word += alphabet[Math.floor(rand() * 26)];
      words.push(word);
      length += 1 + wordLength;
    }
    return [words.join(' '), pickLetters(alphabet, Math.floor(rand() * 6))];
  }
  const pool = rand() < 0.5 ? 'abc' : 'abcdef';
  const wordCount = 1 + Math.floor(rand() * 6);
  const words = [];
  for (let w = 0; w < wordCount; w++) {
    const wordLength = 1 + Math.floor(rand() * 4);
    let word = '';
    for (let i = 0; i < wordLength; i++) word += pool[Math.floor(rand() * pool.length)];
    words.push(word);
  }
  return [words.join(' '), pickLetters(pool, Math.floor(rand() * (pool.length + 1)))];
}
